local ctx = service or activity
local base_dir_path = Environment.getExternalStorageDirectory().getAbsolutePath() .. "/ananda saputra sari/TexaBlogger"
local base_dir_file = File(base_dir_path)
if not base_dir_file.exists() then
    base_dir_file.mkdirs()
end
local auth_config_file = base_dir_path .. "/AuthConfig.json"

local client_id = ""
local client_secret = ""
local refresh_token = ""
local blog_id = ""
local blog_name = ""
local blog_url = ""
local access_token = ""
local access_token_expiry = 0

local function loadAuthConfig()
    local f = io.open(auth_config_file, "r")
    if f then
        local content = f:read("*a")
        f:close()
        local s, root = pcall(function() return JSONObject(content) end)
        if s then
            client_id = root.optString("client_id", "")
            client_secret = root.optString("client_secret", "")
            refresh_token = root.optString("refresh_token", "")
            blog_id = root.optString("blog_id", "")
            blog_name = root.optString("blog_name", "")
            blog_url = root.optString("blog_url", "")
            access_token = root.optString("access_token", "")
            access_token_expiry = root.optLong("access_token_expiry", 0)
        end
    end
end

local function saveAuthConfig()
    local root = JSONObject()
    root.put("client_id", client_id)
    root.put("client_secret", client_secret)
    root.put("refresh_token", refresh_token)
    root.put("blog_id", blog_id)
    root.put("blog_name", blog_name)
    root.put("blog_url", blog_url)
    root.put("access_token", access_token)
    root.put("access_token_expiry", access_token_expiry)
    local f = io.open(auth_config_file, "w")
    if f then
        f:write(root.toString())
        f:close()
    end
end

loadAuthConfig()

local function refreshAccessTokenIfNeeded(callback)
    local current_time = os.time()
    if access_token ~= "" and current_time < (access_token_expiry - 300) then
        if callback then callback(true) end
        return
    end

    if refresh_token == "" or client_id == "" or client_secret == "" then
        if callback then callback(false) end
        return
    end

    task(function(t_client_id, t_client_secret, t_refresh_token)
        require "import"
        import "java.net.URL"
        import "java.io.DataOutputStream"
        import "java.io.BufferedReader"
        import "java.io.InputStreamReader"
        import "java.net.URLEncoder"
        import "org.json.JSONObject"

        local code = -1
        local resBody = ""
        pcall(function()
            local urlStr = "https://oauth2.googleapis.com/token"
            local data = "client_id=" .. URLEncoder.encode(t_client_id, "UTF-8") ..
                         "&client_secret=" .. URLEncoder.encode(t_client_secret, "UTF-8") ..
                         "&refresh_token=" .. URLEncoder.encode(t_refresh_token, "UTF-8") ..
                         "&grant_type=refresh_token"
                         
            local url = URL(urlStr)
            local conn = url.openConnection()
            conn.setConnectTimeout(10000)
            conn.setReadTimeout(10000)
            conn.setRequestMethod("POST")
            conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded")
            conn.setDoOutput(true)

            local out = DataOutputStream(conn.getOutputStream())
            out.writeBytes(data)
            out.flush()
            out.close()

            code = conn.getResponseCode()
            local isStream = (code >= 200 and code < 300) and conn.getInputStream() or conn.getErrorStream()
            if isStream then
                local br = BufferedReader(InputStreamReader(isStream))
                local line = br.readLine()
                while line ~= nil do
                    resBody = resBody .. line
                    line = br.readLine()
                end
                br.close()
            end
        end)
        return code, resBody
    end, client_id, client_secret, refresh_token, function(code, body)
        local s, data = pcall(function() return JSONObject(body) end)
        if code == 200 and s and data.has("access_token") then
            access_token = data.getString("access_token")
            local expires_in = data.optInt("expires_in", 3600)
            access_token_expiry = os.time() + expires_in
            saveAuthConfig()
            if callback then callback(true) end
        else
            if callback then callback(false) end
        end
    end)
end

