local function performLocalSearch(query)
    local q = tostring(query):lower()
    local container = (currentTab == "posts" and views.postsListContainer) or (currentTab == "pages" and views.pagesListContainer) or views.blogsListContainer
    
    for i = 0, container.getChildCount() - 1, 2 do
        local itemLayout = container.getChildAt(i)
        local div = container.getChildAt(i + 1)
        
        if itemLayout then
            local title = ""
            pcall(function()
                if currentTab == "blogs" then
                    title = tostring(itemLayout.getChildAt(0).getText())
                else
                    title = tostring(itemLayout.getChildAt(0).getChildAt(0).getText())
                end
            end)
            
            if title:lower():find(q, 1, true) then
                itemLayout.setVisibility(0)
                if div then div.setVisibility(0) end
            else
                itemLayout.setVisibility(8)
                if div then div.setVisibility(8) end
            end
        end
    end
end

local searchTw = TextWatcher{
    onTextChanged = function(s, start, before, count) performLocalSearch(s) end,
    beforeTextChanged = function(s, start, count, after) end,
    afterTextChanged = function(s) end
}
views.inputSearch.addTextChangedListener(searchTw)

import "android.speech.SpeechRecognizer"
import "android.speech.RecognizerIntent"
import "android.speech.RecognitionListener"
import "android.content.Intent"

pcall(function()
    local speechRecognizer = SpeechRecognizer.createSpeechRecognizer(ctx)
    local recognizerIntent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH)
    recognizerIntent.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
    
    speechRecognizer.setRecognitionListener(RecognitionListener{
        onResults = function(results)
            local matches = results.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
            if matches and matches.size() > 0 then
                views.inputSearch.setText(matches.get(0))
            end
            views.inputSearch.setHint("Cari...")
        end,
        onReadyForSpeech = function(params) views.inputSearch.setHint("Mendengarkan...") end,
        onBeginningOfSpeech = function() end,
        onRmsChanged = function(rmsdB) end,
        onBufferReceived = function(buffer) end,
        onEndOfSpeech = function() views.inputSearch.setHint("Memproses...") end,
        onError = function(error) views.inputSearch.setHint("Cari...") end,
        onPartialResults = function(partialResults) end,
        onEvent = function(eventType, params) end
    })
    
    views.btnVoiceSearch.onClick = function()
        views.inputSearch.setText("")
        speechRecognizer.startListening(recognizerIntent)
    end
end)

