import "android.text.Html"
import "android.content.ClipData"
import "android.content.Context"

local function getSmartSnippet(htmlContent)
    if not htmlContent or htmlContent == "" then return "" end
    local plainText = ""
    if Build.VERSION.SDK_INT >= 24 then
        plainText = Html.fromHtml(htmlContent, Html.FROM_HTML_MODE_LEGACY).toString()
    else
        plainText = Html.fromHtml(htmlContent).toString()
    end
    
    plainText = plainText:gsub("^%s+", ""):gsub("%s+$", "")
    
    if #plainText <= 500 then
        return plainText
    end
    
    local snippet = plainText:sub(1, 500)
    local pos = 0
    for i = 500, 1, -1 do
        local c = snippet:sub(i, i)
        if c == "." or c == "!" or c == "?" then
            pos = i
            break
        end
    end
    
    if pos > 0 then
        return snippet:sub(1, pos)
    else
        for i = 500, 1, -1 do
            if snippet:sub(i, i) == " " then
                pos = i
                break
            end
        end
        if pos > 0 then
            return snippet:sub(1, pos - 1) .. "..."
        else
            return snippet .. "..."
        end
    end
end

local function showCommentDialog(itemType, itemTitle, itemId, currentStatus)
    local d = Dialog(ctx)
    d.requestWindowFeature(1)
    
    local bg = GradientDrawable()
    bg.setColor(0xFFFFFFFF)
    bg.setCornerRadius(24)
    
    local dLayout = LinearLayout(ctx)
    dLayout.setOrientation(1)
    dLayout.setBackgroundDrawable(bg)
    dLayout.setPadding(64, 64, 64, 64)
    
    local tvTitleHeader = TextView(ctx)
    tvTitleHeader.setText("Izin Komentar")
    tvTitleHeader.setTextSize(20)
    tvTitleHeader.setTypeface(Typeface.DEFAULT_BOLD)
    tvTitleHeader.setTextColor(0xFF202124)
    tvTitleHeader.setPadding(0, 0, 0, 16)
    
    local tvMsg = TextView(ctx)
    tvMsg.setText(itemTitle)
    tvMsg.setTextSize(14)
    tvMsg.setTextColor(0xFF5F6368)
    tvMsg.setPadding(0, 0, 0, 32)
    
    local rg = RadioGroup(ctx)
    rg.setOrientation(1)
    rg.setLayoutParams(LinearLayout.LayoutParams(-1, -2))
    
    local rbAllow = RadioButton(ctx)
    rbAllow.setText("Izinkan")
    rbAllow.setTextSize(16)
    rbAllow.setTextColor(0xFF202124)
    rbAllow.setPadding(0, 16, 0, 16)
    
    local rbShow = RadioButton(ctx)
    rbShow.setText("Jangan izinkan, tampilkan yang ada")
    rbShow.setTextSize(16)
    rbShow.setTextColor(0xFF202124)
    rbShow.setPadding(0, 16, 0, 16)
    
    local rbHide = RadioButton(ctx)
    rbHide.setText("Jangan izinkan, sembunyikan yang ada")
    rbHide.setTextSize(16)
    rbHide.setTextColor(0xFF202124)
    rbHide.setPadding(0, 16, 0, 16)
    
    rg.addView(rbAllow)
    rg.addView(rbShow)
    rg.addView(rbHide)
    
    if currentStatus == "DONT_ALLOW_SHOW_EXISTING" then
        rbShow.setChecked(true)
    elseif currentStatus == "DONT_ALLOW_HIDE_EXISTING" then
        rbHide.setChecked(true)
    else
        rbAllow.setChecked(true)
    end
    
    local btnContainer = LinearLayout(ctx)
    btnContainer.setOrientation(0)
    btnContainer.setLayoutParams(LinearLayout.LayoutParams(-1, -2))
    btnContainer.setGravity(Gravity.RIGHT)
    btnContainer.setPadding(0, 32, 0, 0)
    
    local btnBatal = TextView(ctx)
    btnBatal.setText("Batal")
    btnBatal.setTextSize(16)
    btnBatal.setTextColor(0xFF5F6368)
    btnBatal.setPadding(32, 32, 32, 32)
    btnBatal.setClickable(true)
    
    local btnSimpan = TextView(ctx)
    btnSimpan.setText("OK")
    btnSimpan.setTextSize(16)
    btnSimpan.setTextColor(0xFFF57C00)
    btnSimpan.setTypeface(Typeface.DEFAULT_BOLD)
    btnSimpan.setPadding(32, 32, 32, 32)
    btnSimpan.setClickable(true)
    
    btnContainer.addView(btnBatal)
    btnContainer.addView(btnSimpan)
    
    dLayout.addView(tvTitleHeader)
    dLayout.addView(tvMsg)
    dLayout.addView(rg)
    dLayout.addView(btnContainer)
    
    d.setContentView(dLayout)
    
    local window = d.getWindow()
    if Build.VERSION.SDK_INT >= 22 then
        window.setType(2032)
    else
        window.setType(2003)
    end
    window.setBackgroundDrawable(ColorDrawable(0x00000000))
    
    local lp = window.getAttributes()
    lp.width = ctx.getResources().getDisplayMetrics().widthPixels * 0.85
    window.setAttributes(lp)
    
    btnBatal.onClick = function() d.dismiss() end
    
    btnSimpan.onClick = function()
        d.dismiss()
        
        local selectedVal = "ALLOW"
        if rbShow.isChecked() then
            selectedVal = "DONT_ALLOW_SHOW_EXISTING"
        elseif rbHide.isChecked() then
            selectedVal = "DONT_ALLOW_HIDE_EXISTING"
        end
        
        if selectedVal == currentStatus then return end
        
        refreshAccessTokenIfNeeded(function(success)
            if not success then return end
            task(function(t_tok, t_blog, t_item, t_type, t_val)
                require "import"
                import "java.net.URL"
                import "java.io.DataOutputStream"
                import "org.json.JSONObject"
                local c = -1
                pcall(function()
                    local urlStr = "https://www.googleapis.com/blogger/v3/blogs/" .. t_blog .. "/" .. t_type .. "/" .. t_item
                    local url = URL(urlStr)
                    local conn = url.openConnection()
                    conn.setRequestMethod("POST")
                    conn.setRequestProperty("X-HTTP-Method-Override", "PATCH")
                    conn.setRequestProperty("Authorization", "Bearer " .. t_tok)
                    conn.setRequestProperty("Content-Type", "application/json")
                    conn.setDoOutput(true)
                    
                    local reqJson = JSONObject()
                    reqJson.put("readerComments", t_val)
                    
                    local out = DataOutputStream(conn.getOutputStream())
                    out.writeBytes(reqJson.toString())
                    out.flush()
                    out.close()
                    
                    c = conn.getResponseCode()
                end)
                return c, t_type, t_item, t_val
            end, access_token, blog_id, itemId, (itemType == "postingan" and "posts" or "pages"), selectedVal, function(c, t_type, t_item, t_val)
                if c == 200 then
                    if t_type == "posts" then 
                        _G.loadPosts() 
                    else 
                        _G.pageCommentsCache = _G.pageCommentsCache or {}
                        _G.pageCommentsCache[t_item] = t_val
                        _G.loadPages() 
                    end
                end
            end)
        end)
    end
    
    d.show()
end

