        end
    end
    
    local function renderLabels()
        labelsContainer.removeAllViews()
        for i, lbl in ipairs(currentLabels) do
            local itemLayout = LinearLayout(ctx)
            itemLayout.setOrientation(0)
            itemLayout.setLayoutParams(LinearLayout.LayoutParams(-1, -2))
            itemLayout.setGravity(Gravity.CENTER_VERTICAL)
