            btnHapus.setTextColor(0xFFD93025)
            btnHapus.setTypeface(Typeface.DEFAULT_BOLD)
            btnHapus.setPadding(32, 16, 32, 16)
            btnHapus.setClickable(true)
            btnHapus.setContentDescription("Hapus label " .. lbl)
            
            btnHapus.onClick = function()
                table.remove(currentLabels, i)
                renderLabels()
            end
            
            itemLayout.addView(tvLbl)
            itemLayout.addView(btnHapus)
            
            local div = View(ctx)
            div.setLayoutParams(LinearLayout.LayoutParams(-1, 2))
            div.setBackgroundColor(0xFFE0E0E0)
            
            labelsContainer.addView(itemLayout)
            labelsContainer.addView(div)
        end
    end
    
    renderLabels()
    
    btnTambah.onClick = function()
        local newLbl = tostring(inputLabel.getText()):gsub("^%s+", ""):gsub("%s+$", "")
        if newLbl ~= "" then
            table.insert(currentLabels, newLbl)
            inputLabel.setText("")
            renderLabels()
            local imm = ctx.getSystemService(Context.INPUT_METHOD_SERVICE)
            imm.hideSoftInputFromWindow(inputLabel.getWindowToken(), 0)
        end
    end
    
    btnBatal.onClick = function() d.dismiss() end
    
    btnSimpan.onClick = function()
        d.dismiss()
        refreshAccessTokenIfNeeded(function(success)
            if not success then return end
            task(function(t_tok, t_blog, t_item, t_labels)
                require "import"
                import "java.net.URL"
                import "java.io.DataOutputStream"
                import "org.json.JSONObject"
                import "org.json.JSONArray"
                import "java.lang.String"
                
                local c = -1
                pcall(function()
                    local urlStr = "https://www.googleapis.com/blogger/v3/blogs/" .. t_blog .. "/posts/" .. t_item
                    local url = URL(urlStr)
                    local conn = url.openConnection()
                    conn.setRequestMethod("POST")
                    conn.setRequestProperty("X-HTTP-Method-Override", "PATCH")
                    conn.setRequestProperty("Authorization", "Bearer " .. t_tok)
                    conn.setRequestProperty("Content-Type", "application/json; charset=UTF-8")
                    conn.setDoOutput(true)
                    
                    local reqJson = JSONObject()
                    local arr = JSONArray()
                    if t_labels and t_labels ~= "" then
                        for s in string.gmatch(t_labels, "([^,]+)") do
                            arr.put(s)
                        end
                    end
                    reqJson.put("labels", arr)
                    
                    local jsonString = reqJson.toString()
                    local bytes = String(jsonString).getBytes("UTF-8")
                    
                    local out = DataOutputStream(conn.getOutputStream())
                    out.write(bytes)
                    out.flush()
                    out.close()
                    
                    c = conn.getResponseCode()
                end)
                return c
            end, access_token, blog_id, itemId, table.concat(currentLabels, ","), function(c)
                if c == 200 then
                    _G.loadPosts()
                end
            end)
        end)
    end
    
    d.show()
end

