                    local c = -1
                    pcall(function()
                        local urlStr = "https://www.googleapis.com/blogger/v3/blogs/" .. t_blog .. "/posts/" .. t_item .. "/" .. t_act
                        local url = URL(urlStr)
                        local conn = url.openConnection()
                        conn.setRequestMethod("POST")
                        conn.setRequestProperty("Authorization", "Bearer " .. t_tok)
                        conn.setRequestProperty("Content-Length", "0")
                        c = conn.getResponseCode()
                    end)
                    return c
                end, access_token, blog_id, itemId, actionPath, function(c)
                    if c == 200 or c == 204 then
                        _G.loadPosts()
                    end
                end)
            end)
