        local shareIntent = Intent(Intent.ACTION_SEND)
        shareIntent.setType("text/plain")
        shareIntent.putExtra(Intent.EXTRA_SUBJECT, itemTitle)
        shareIntent.putExtra(Intent.EXTRA_TEXT, shareText)
        
        d.dismiss()
        dialog.dismiss()
        
        local chooser = Intent.createChooser(shareIntent, "Bagikan via")
        chooser.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        ctx.startActivity(chooser)
    end
    
    btnSalin.onClick = function()
        local clipboard = ctx.getSystemService(Context.CLIPBOARD_SERVICE)
        local clip = ClipData.newPlainText("Blogger", itemTitle .. "\n" .. itemUrl)
        clipboard.setPrimaryClip(clip)
