    end
    
    btnHapus.onClick = function()
        if not isConfirming then
            isConfirming = true
            tvMsg.setText("Yakin ingin menghapus ini?")
            btnHapus.setText("Ya, Hapus")
            btnHapus.setTextColor(0xFFD93025)
        else
            d.dismiss()
            refreshAccessTokenIfNeeded(function(success)
                if not success then return end
                task(function(t_tok, t_blog, t_item, t_type)
                    require "import"
                    import "java.net.URL"
                    local c = -1
                    pcall(function()
                        local urlStr = "https://www.googleapis.com/blogger/v3/blogs/" .. t_blog .. "/" .. t_type .. "/" .. t_item
                        local url = URL(urlStr)
                        local conn = url.openConnection()
                        conn.setRequestMethod("DELETE")
                        conn.setRequestProperty("Authorization", "Bearer " .. t_tok)
                        c = conn.getResponseCode()
                    end)
                    return c, t_type
                end, access_token, blog_id, itemId, (itemType == "postingan" and "posts" or "pages"), function(c, t_type)
                    if c == 200 or c == 204 then
                        if t_type == "posts" then _G.loadPosts() else _G.loadPages() end
                    end
                end)
            end)
        end
    end
    
    d.show()
end

