local function switchTab(tabName)
    currentTab = tabName
    views.containerPosts.setVisibility(8)
    views.containerPages.setVisibility(8)
    views.containerBlogs.setVisibility(8)
    
    views.tabPosts.setTextColor(0xFF5F6368)
    views.tabPages.setTextColor(0xFF5F6368)
    views.tabBlogs.setTextColor(0xFF5F6368)
    
    views.tabPosts.setTypeface(Typeface.DEFAULT)
    views.tabPages.setTypeface(Typeface.DEFAULT)
    views.tabBlogs.setTypeface(Typeface.DEFAULT)
    
    views.tabPosts.setContentDescription("Tab Postingan")
    views.tabPages.setContentDescription("Tab Halaman")
    views.tabBlogs.setContentDescription("Tab Daftar Blog")
    
    views.inputSearch.setText("")
    
    if tabName == "posts" then
        views.inputSearch.setHint("Cari Postingan...")
        views.containerPosts.setVisibility(0)
        views.tabPosts.setTextColor(0xFFF57C00)
        views.tabPosts.setTypeface(Typeface.DEFAULT_BOLD)
