views.btnFormatCepat.onClick = function()
    local rawText = tostring(views.editInputContent.getText())
    if rawText == "" then return end
    
    local lines = {}
    for line in (rawText.."\n"):gmatch("(.-)\n") do
        table.insert(lines, line)
    end
    
    local finalText = ""
    local inUList = false
    local inOList = false
    local inQuote = false
    local inParagraph = false
    
    local function closeLists()
        if inUList then
            finalText = finalText .. "</ul>\n"
            inUList = false
        end
        if inOList then
            finalText = finalText .. "</ol>\n"
            inOList = false
        end
    end
    
    local function closeQuote()
        if inQuote then
            finalText = finalText .. "</p>\n</blockquote>\n"
            inQuote = false
        end
    end
    
    local function closeParagraph()
        if inParagraph then
            finalText = finalText .. "</p>\n"
            inParagraph = false
        end
    end
    
    local function closeAll()
        closeLists()
        closeQuote()
        closeParagraph()
    end
    
    local function parseInline(t)
        t = t:gsub("%*%*(.-)%*%*", "<strong>%1</strong>")
        t = t:gsub("%*(.-)%*", "<em>%1</em>")
        t = t:gsub("%[(.-)%]%((.-)%)", "<a href=\"%2\">%1</a>")
        return t
    end
    
    for i, line in ipairs(lines) do
        local trimmed = line:gsub("\226\128\139", "")
        trimmed = trimmed:gsub("\r", "")
        trimmed = trimmed:gsub("^%s+", ""):gsub("%s+$", "")
        trimmed = trimmed:gsub("  +", " ")
        
        if trimmed == "" then
            closeAll()
        else
            local hr = trimmed:match("^%-%-%-%s*$")
            local hashes, hText = trimmed:match("^(#+)%s*(.*)")
            local bq = trimmed:match("^>%s*(.*)")
            
            local uli
            if not hr and trimmed:sub(1, 1) == "-" then
                uli = trimmed:match("^%-%s*(.*)")
            elseif trimmed:sub(1, 1) == "*" and trimmed:sub(1, 2) ~= "**" then
                uli = trimmed:match("^%*%s*(.*)")
            end
            
            local oli = trimmed:match("^%d+%.%s*(.*)")
            
            if hr then
                closeAll()
                finalText = finalText .. "<hr>\n"
            elseif hashes then
                closeAll()
                local level = #hashes
                if level > 6 then level = 6 end
                finalText = finalText .. "<h" .. level .. ">" .. parseInline(hText) .. "</h" .. level .. ">\n"
            elseif uli then
                closeQuote()
                closeParagraph()
                if inOList then closeLists() end
                if not inUList then
                    finalText = finalText .. "<ul>\n"
                    inUList = true
                end
                finalText = finalText .. "<li>" .. parseInline(uli) .. "</li>\n"
            elseif oli then
                closeQuote()
                closeParagraph()
                if inUList then closeLists() end
                if not inOList then
                    finalText = finalText .. "<ol>\n"
                    inOList = true
                end
                finalText = finalText .. "<li>" .. parseInline(oli) .. "</li>\n"
            elseif bq then
                closeLists()
                closeParagraph()
                if not inQuote then
                    finalText = finalText .. "<blockquote>\n<p>" .. parseInline(bq)
                    inQuote = true
                else
                    finalText = finalText .. "<br>\n" .. parseInline(bq)
                end
            else
                closeLists()
                closeQuote()
                if not inParagraph then
                    finalText = finalText .. "<p>" .. parseInline(trimmed)
                    inParagraph = true
                else
                    finalText = finalText .. "<br>\n" .. parseInline(trimmed)
                end
            end
        end
    end
    
    closeAll()
    
    views.editInputContent.setText(finalText)
end

