views.btnEditUpdate.onClick = function()
    local t = tostring(views.editInputTitle.getText())
    local c = tostring(views.editInputContent.getText())
    
    local imm = ctx.getSystemService(Context.INPUT_METHOD_SERVICE)
    imm.hideSoftInputFromWindow(views.editInputTitle.getWindowToken(), 0)
    
    views.btnEditUpdate.setEnabled(false)
    views.btnEditUpdate.setBackgroundColor(0xFFBDBDBD)
    views.btnEditUpdate.setText(currentEditMode == "create" and "Menyimpan..." or "Memperbaharui...")
    
    refreshAccessTokenIfNeeded(function(success)
        if not success then
            validateEditInput()
            return
        end
        
        task(function(t_tok, t_blog, t_post, new_title, new_content, t_type, t_mode, t_comments)
            require "import"
            import "java.net.URL"
            import "java.io.DataOutputStream"
            import "org.json.JSONObject"
            import "java.lang.String"
            
            local code = -1
            pcall(function()
                local typePath = (t_type == "postingan") and "posts" or "pages"
                local urlStr = "https://www.googleapis.com/blogger/v3/blogs/" .. t_blog .. "/" .. typePath
                
                if t_mode == "edit" then
                    urlStr = urlStr .. "/" .. t_post
                else
                    urlStr = urlStr .. "/?isDraft=false"
                end
                
                local url = URL(urlStr)
                local conn = url.openConnection()
                if t_mode == "create" then
                    conn.setRequestMethod("POST")
                else
                    conn.setRequestMethod("PUT")
                end
                conn.setRequestProperty("Authorization", "Bearer " .. t_tok)
                conn.setRequestProperty("Content-Type", "application/json; charset=UTF-8")
                conn.setDoOutput(true)
                
                local reqJson = JSONObject()
                if t_mode == "create" then
                    reqJson.put("kind", (t_type == "postingan") and "blogger#post" or "blogger#page")
                    local blogObj = JSONObject()
                    blogObj.put("id", t_blog)
                    reqJson.put("blog", blogObj)
                end
                
                reqJson.put("title", new_title)
                reqJson.put("content", new_content)
                reqJson.put("readerComments", t_comments)
                
                local jsonString = reqJson.toString()
                local bytes = String(jsonString).getBytes("UTF-8")
                
                local out = DataOutputStream(conn.getOutputStream())
                out.write(bytes)
                out.flush()
                out.close()
                
                code = conn.getResponseCode()
            end)
            return code, t_type, t_post, t_comments
        end, access_token, blog_id, currentEditPostId, t, c, currentEditType, currentEditMode, editCurrentComments, function(code, t_type, t_post, t_comments)
            views.btnEditUpdate.setText(currentEditMode == "create" and "Simpan" or "Perbaharui")
            if code >= 200 and code < 300 then
                if t_type == "halaman" and t_post and t_post ~= "" then
                    _G.pageCommentsCache = _G.pageCommentsCache or {}
                    _G.pageCommentsCache[t_post] = t_comments
                end
                showScreen("home")
                if currentEditType == "postingan" then
                    _G.loadPosts()
                else
                    _G.loadPages()
                end
            else
                validateEditInput()
            end
        end)
    end)
end

