_G.loadBlogs = function()
    views.blogsListContainer.removeAllViews()
    views.emptyBlogsText.setText("Sedang memuat data, silakan tunggu berapa saat, ya.")
    views.emptyBlogsText.setVisibility(0)
    
    if client_id == "" or client_secret == "" or refresh_token == "" then
        views.emptyBlogsText.setText("Kredensial API belum dikonfigurasi.")
        return
    end
    
    refreshAccessTokenIfNeeded(function(success)
        if not success then
            views.emptyBlogsText.setText("Gagal menyegarkan sesi. Periksa koneksi atau kredensial Anda.")
            return
        end
        
        task(function(t_token)
            require "import"
            import "java.net.URL"
            import "java.io.BufferedReader"
            import "java.io.InputStreamReader"
            import "org.json.JSONObject"
            
            local code = -1
            local resBody = ""
            pcall(function()
                local url = URL("https://www.googleapis.com/blogger/v3/users/self/blogs")
                local conn = url.openConnection()
                conn.setConnectTimeout(10000)
                conn.setReadTimeout(10000)
                conn.setRequestMethod("GET")
                conn.setRequestProperty("Authorization", "Bearer " .. t_token)
                
                code = conn.getResponseCode()
                local isStream = (code >= 200 and code < 300) and conn.getInputStream() or conn.getErrorStream()
                if isStream then
                    local br = BufferedReader(InputStreamReader(isStream))
                    local line = br.readLine()
                    while line ~= nil do
                        resBody = resBody .. line
                        line = br.readLine()
                    end
                    br.close()
                end
            end)
            return code, resBody
        end, access_token, function(code, body)
            if code == 200 then
                local s, data = pcall(function() return JSONObject(body) end)
                if s and data.has("items") then
                    local items = data.getJSONArray("items")
                    local count = items.length()
                    if count == 0 then
                        views.emptyBlogsText.setText("Tidak ada blog yang ditemukan.")
                        return
                    end
                    
                    views.emptyBlogsText.setVisibility(8)
                    
                    for i = 0, count - 1 do
                        local blogObj = items.getJSONObject(i)
                        local bId = blogObj.optString("id", "")
                        local bName = blogObj.optString("name", "Tanpa Nama")
                        local bUrl = blogObj.optString("url", "")
                        local bUpdated = blogObj.optString("updated", "")
                        
                        local itemLayout = LinearLayout(ctx)
                        itemLayout.setOrientation(1)
                        itemLayout.setLayoutParams(LinearLayout.LayoutParams(-1, -2))
                        itemLayout.setPadding(32, 32, 32, 32)
                        
                        local tvName = TextView(ctx)
                        tvName.setText(bName)
                        tvName.setTextSize(18)
                        tvName.setTextColor(0xFF202124)
                        tvName.setTypeface(Typeface.DEFAULT_BOLD)
                        
                        local tvUrl = TextView(ctx)
                        tvUrl.setText(bUrl)
                        tvUrl.setTextSize(14)
                        tvUrl.setTextColor(0xFF1A73E8)
                        tvUrl.setPadding(0, 4, 0, 4)
                        
                        local tvUpdated = TextView(ctx)
                        tvUpdated.setText("Diperbarui: " .. bUpdated)
                        tvUpdated.setTextSize(12)
                        tvUpdated.setTextColor(0xFF5F6368)
                        
                        local btnPilih = TextView(ctx)
                        btnPilih.setText("Pilih Blog")
                        btnPilih.setTextSize(14)
                        btnPilih.setTextColor(0xFFFFFFFF)
                        btnPilih.setBackgroundColor(0xFF34A853)
                        btnPilih.setGravity(Gravity.CENTER)
                        btnPilih.setPadding(16, 16, 16, 16)
                        
                        local btnParams = LinearLayout.LayoutParams(-1, -2)
                        btnParams.setMargins(0, 16, 0, 0)
                        btnPilih.setLayoutParams(btnParams)
                        btnPilih.setClickable(true)
                        btnPilih.setFocusable(true)
                        
                        itemLayout.addView(tvName)
                        itemLayout.addView(tvUrl)
                        itemLayout.addView(tvUpdated)
                        itemLayout.addView(btnPilih)
                        
                        local div = View(ctx)
                        div.setLayoutParams(LinearLayout.LayoutParams(-1, 2))
                        div.setBackgroundColor(0xFFE0E0E0)
                        
                        views.blogsListContainer.addView(itemLayout)
                        views.blogsListContainer.addView(div)
                        
                        btnPilih.onClick = function()
                            blog_id = bId
                            blog_name = bName
                            blog_url = bUrl
                            saveAuthConfig()
                            views.tvSelectedBlog.setText(blog_name)
                            switchTab("posts")
                        end
                    end
                else
                    views.emptyBlogsText.setText("Tidak ada blog yang ditemukan.")
                end
            elseif code == -1 then
                views.emptyBlogsText.setText("Tidak ada koneksi internet, silakan coba lagi dan pastikan menggunakan jaringan yang stabil, ya.")
            else
                local errMsg = ""
                local s, errData = pcall(function() return JSONObject(body) end)
                if s and errData.has("error") then
                    pcall(function()
                        errMsg = errData.getJSONObject("error").optString("message", "")
                    end)
                end
                if errMsg == "" then
                    errMsg = body
                end
                if errMsg == "" or errMsg == nil then
                    errMsg = "Tidak ada keterangan tambahan."
                end
                views.emptyBlogsText.setText("Gagal memuat blog. Kode kesalahan: " .. tostring(code) .. "\nKeterangan: " .. tostring(errMsg))
            end
        end)
    end)
end

